            aCross ^= (RotL64(pCrossLaneC[((S_BLOCK1 - aIndex + 736U)) & S_BLOCK1], 19U) ^ RotL64(pCrossLaneD[((aIndex + 5338U)) & S_BLOCK1], 53U));
            aCross = TwistMix64::DiffuseA((aCross ^ aTwistDomainWordCross));
            //
            aScatter = (RotL64(aIngress, 56U) + RotL64(aCross, 5U)) + (RotL64(aPrevious, 27U) ^ RotL64(aCarry, 39U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aTwistDomainWordScatter));
            //
            aOrbiterD = (aWandererH + RotL64(aIngress, 50U)) + 0x89CEB68611AAD167ULL;
            aOrbiterC = ((aWandererJ + RotL64(aCross, 57U)) + RotL64(aCarry, 41U)) + 0x5E82607F67EC1F27ULL;
            aOrbiterH = ((aWandererE + RotL64(aPrevious, 11U)) + 0xB4F3A627661BFA30ULL) + aOASaltB[(((511U - aIndex) + 445U)) & S_SALT1];
            aOrbiterF = (((aWandererK + RotL64(aScatter, 43U)) + RotL64(aCarry, 27U)) + 0xEB2AF6354E55ED8DULL) + aOASaltA[((aIndex + 182U)) & S_SALT1];
            aOrbiterI = ((aWandererF + RotL64(aPrevious, 37U)) + RotL64(aCarry, 57U)) + 0x83A44A94D42381BFULL;
            aOrbiterE = (aWandererC + RotL64(aCross, 5U)) + 0xA10D6EDDB937ABDBULL;
            aOrbiterK = ((aWandererA + RotL64(aScatter, 19U)) + 0xF99F2C392C495499ULL) + aOASaltC[(((511U - aIndex) + 58U)) & S_SALT1];
            //
            aOrbiterD = ((aOrbiterD + aOrbiterC) + 0x3E8F02E4ED23CC38ULL) + aOUSaltF[((aIndex + 307U)) & S_SALT1];
            aOrbiterH = (aOrbiterH ^ aOrbiterD) ^ 0x78C85F308D40B2CAULL;
            aOrbiterH = RotL64((aOrbiterH * 0x306D3E9195963EE1ULL), 29U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterF) + 0x652551884651B963ULL;
            aOrbiterI = (aOrbiterI ^ aOrbiterC) ^ 0x7AAECD64DE91455FULL;
            aOrbiterI = RotL64((aOrbiterI * 0xE39C7DD66A1AB1F5ULL), 47U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterE) + 0x7808A3CB88B22E83ULL;
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0xEEA6EB575DACC28AULL;
            aOrbiterD = RotL64((aOrbiterD * 0xBEB9A938C82A11DDULL), 11U);
            //
            aOrbiterE = ((aOrbiterE + aOrbiterK) + 0x91E1614BDAB77EB6ULL) + aOUSaltG[((aIndex + 235U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterE) ^ 0xD42A96256D2A90B7ULL;
            aOrbiterC = RotL64((aOrbiterC * 0xF6347B8B852F3EC3ULL), 41U);
            //
            aOrbiterI = (aOrbiterI + aOrbiterD) + 0x05CF1F7CE7B8D812ULL;
            aOrbiterK = (aOrbiterK ^ aOrbiterI) ^ 0xDA9AD23DAC51D2C2ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xD991983B259E8B39ULL), 57U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterI) + 0x2415070AF6363A2AULL;
            aOrbiterE = ((aOrbiterE ^ aOrbiterH) ^ 0x873A92928CB53E70ULL) ^ aOUSaltA[((aIndex + 283U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0xBBE10931C71684BFULL), 3U);
            //
            aOrbiterK = (aOrbiterK + aOrbiterH) + 0x9B3354ACEBB5B672ULL;
            aOrbiterF = ((aOrbiterF ^ aOrbiterK) ^ 0x944E6BE7F0D127B5ULL) ^ aOUSaltD[((aIndex + 126U)) & S_SALT1];
            aOrbiterF = RotL64((aOrbiterF * 0x16408BB97B6E2D1FULL), 19U);
            //
            aIngress = aOrbiterF ^ RotL64(aOrbiterD, 6U);
            aIngress = aIngress + (aOrbiterE ^ RotL64(aOrbiterK, 13U));
            aIngress = aIngress + (RotL64(aOrbiterI, 23U) ^ aOrbiterH);
