            aWandererC = aWandererC + ((((RotL64(aPrevious, 43U) + RotL64(aOrbiterI, 11U)) + aOrbiterH) + RotL64(aCarry, 37U)) + aWUSaltC[(((511U - aIndex) + 220U)) & S_SALT1]);
            //
