            aCarry = aCarry + (RotL64(aWandererK, 34U) ^ aWandererJ);
            aCarry = aCarry + RotL64(aWandererA, 13U);
            aCarry = aCarry + RotL64(aIngress, 21U);
            aCarry = TwistMix64::DiffuseC(aCarry);
