            aOrbiterF = ((aWandererA + RotL64(aScatter, 11U)) + 0x7C4351947B893887ULL) + aOASaltA[((aIndex + 91U)) & S_SALT1];
            aOrbiterH = ((aWandererH + RotL64(aIngress, 47U)) + RotL64(aCarry, 35U)) + 0xAFDBE5E8B0862925ULL;
            aOrbiterB = (((aWandererI + RotL64(aScatter, 5U)) + RotL64(aCarry, 23U)) + 0x37ABF1C5CDD20CA2ULL) + aOASaltH[(((511U - aIndex) + 21U)) & S_SALT1];
            aOrbiterK = (((aWandererG + RotL64(aCross, 29U)) + RotL64(aCarry, 47U)) + 0xBA91D13D580C3BE7ULL) + aOASaltC[((aIndex + 14U)) & S_SALT1];
            aOrbiterD = ((aWandererK + RotL64(aIngress, 35U)) + 0x906D02E33EDE30AEULL) + aOASaltG[(((511U - aIndex) + 273U)) & S_SALT1];
