            aOrbiterJ = ((aOrbiterJ + aOrbiterE) + 0x78DEB3028CC4A395ULL) + aOUSaltG[((aIndex + 510U)) & S_SALT1];
            aOrbiterF = (aOrbiterF ^ aOrbiterJ) ^ 0x49E2770350A2621FULL;
