            //
            aOrbiterK = ((aOrbiterK + aOrbiterD) + 0xAB0F4166F1A87720ULL) + aOUSaltD[((aIndex + 433U)) & S_SALT1];
            aOrbiterJ = (aOrbiterJ ^ aOrbiterK) ^ 0x58CF6F1ABD53DB79ULL;
