            //
            aOrbiterD = ((aOrbiterD + aOrbiterB) + 0xAB9FC813D6EF5F8BULL) + aOUSaltE[((aIndex + 27U)) & S_SALT1];
            aOrbiterE = ((aOrbiterE ^ aOrbiterD) ^ 0xCC3FA96787E5EB36ULL) ^ aOUSaltB[(((511U - aIndex) + 85U)) & S_SALT1];
            aOrbiterE = RotL64((aOrbiterE * 0x2E7573BB2DF03987ULL), 11U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterH) + 0x8CFD7B4E540F0507ULL) + aOUSaltH[((aIndex + 439U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0x369E20E6DD6499F8ULL;
            aOrbiterD = RotL64((aOrbiterD * 0x5211E1D452563C53ULL), 35U);
            //
            aIngress = aOrbiterK ^ RotL64(aOrbiterF, 11U);
            aIngress = aIngress + (aOrbiterB ^ RotL64(aOrbiterH, 26U));
            aIngress = aIngress + (aOrbiterJ ^ RotL64(aOrbiterD, 19U));
            aIngress = aIngress + RotL64(aOrbiterE, 57U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererJ = aWandererJ + (((RotL64(aIngress, 43U) + aOrbiterE) + RotL64(aOrbiterJ, 13U)) + aWUSaltC[(((511U - aIndex) + 368U)) & S_SALT1]);
            aWandererG = aWandererG ^ ((RotL64(aScatter, 57U) + aOrbiterE) + RotL64(aOrbiterH, 37U));
