            aWandererH = aWandererH ^ (((RotL64(aCross, 35U) + aOrbiterF) + RotL64(aOrbiterH, 60U)) + aWUSaltF[((aIndex + 295U)) & S_SALT1]);
            aWandererA = aWandererA + ((((RotL64(aScatter, 21U) + aOrbiterB) + RotL64(aOrbiterE, 5U)) + RotL64(aCarry, 21U)) + aWUSaltH[(((511U - aIndex) + 440U)) & S_SALT1]);
