            aIngress ^= (RotL64(aCrystalLaneA[((aIndex + 9509U)) & S_BLOCK1], 39U) ^ RotL64(aShadowLaneC[((aIndex + 15684U)) & S_BLOCK1], 5U));
            aIngress = TwistMix64::DiffuseC((aIngress ^ aKeyRotateADomainWordIngress));
            //
            aCross = (RotL64(aWindLaneD[((S_BLOCK1 - aIndex + 10127U)) & S_BLOCK1], 35U) ^ RotL64(aWindLaneB[((S_BLOCK1 - aIndex + 12369U)) & S_BLOCK1], 6U));
            aCross ^= (RotL64(aPlasmaLaneD[((S_BLOCK1 - aIndex + 16011U)) & S_BLOCK1], 51U) ^ RotL64(aShadowLaneA[((S_BLOCK1 - aIndex + 12608U)) & S_BLOCK1], 19U));
            aCross = TwistMix64::DiffuseC((aCross ^ aKeyRotateADomainWordCross));
            //
            aScatter = (RotL64(aPrevious, 21U) + RotL64(aCarry, 4U)) + (RotL64(aCross, 53U) ^ RotL64(aIngress, 41U));
            aScatter = TwistMix64::DiffuseB((aScatter ^ aKeyRotateADomainWordScatter));
            //
            aOrbiterK = ((aWandererG + RotL64(aPrevious, 3U)) + RotL64(aCarry, 51U)) + 0x3F69FA5F93B0EF17ULL;
            aOrbiterE = (((aWandererK + RotL64(aCross, 51U)) + RotL64(aCarry, 11U)) + 0xF4E7861D2F267B1EULL) + aOASaltC[(((511U - aIndex) + 164U)) & S_SALT1];
            aOrbiterA = (aWandererB + RotL64(aScatter, 34U)) + 0x58C30E84846E6673ULL;
            aOrbiterD = (((aWandererH + RotL64(aIngress, 43U)) + RotL64(aCarry, 29U)) + 0xC97F156B2D17ADBAULL) + aOASaltH[(((511U - aIndex) + 258U)) & S_SALT1];
            aOrbiterF = (aWandererJ + RotL64(aPrevious, 57U)) + 0x1623931EBD1E068FULL;
            aOrbiterC = (aWandererC + RotL64(aIngress, 27U)) + 0x2C9851A0714CDD62ULL;
            aOrbiterJ = ((aWandererF + RotL64(aCross, 11U)) + 0xB72986593FB5DBA3ULL) + aOASaltD[(((511U - aIndex) + 217U)) & S_SALT1];
            //
            aOrbiterK = (aOrbiterK + aOrbiterE) + 0xE9E4842D921CD51AULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterK) ^ 0x85E4195D59B1A32CULL;
            aOrbiterA = RotL64((aOrbiterA * 0x17051A64629F1C25ULL), 13U);
            //
            aOrbiterD = (aOrbiterD + aOrbiterA) + 0x4BD36687C9E56936ULL;
            aOrbiterF = (aOrbiterF ^ aOrbiterD) ^ 0xA0FBF6DD1D109A18ULL;
            aOrbiterF = RotL64((aOrbiterF * 0xD177EA0EC8D4E981ULL), 27U);
            //
            aOrbiterF = (aOrbiterF + aOrbiterC) + 0xC131D8E917DE02DDULL;
            aOrbiterE = (aOrbiterE ^ aOrbiterF) ^ 0x999B8921BBC1C860ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x2292BD27EE9264C5ULL), 5U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterJ) + 0x6D92D602428AFBD6ULL) + aOUSaltG[(((511U - aIndex) + 99U)) & S_SALT1];
            aOrbiterC = ((aOrbiterC ^ aOrbiterA) ^ 0x9124D4ED2C8E1E36ULL) ^ aOUSaltF[((aIndex + 505U)) & S_SALT1];
            aOrbiterC = RotL64((aOrbiterC * 0x742256F5E6360509ULL), 51U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterF) + 0x2238D1E6E50B73D9ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterJ) ^ 0xC597E2C436F2C935ULL) ^ aOUSaltB[((aIndex + 125U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xA84C26EF13118A1BULL), 57U);
            //
            aOrbiterC = (aOrbiterC + aOrbiterK) + 0xD20D4A9CC191756DULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterC) ^ 0x35F5DB7F25488F63ULL) ^ aOUSaltE[(((511U - aIndex) + 343U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0x714368241504CF05ULL), 19U);
            //
            aOrbiterE = (aOrbiterE + aOrbiterD) + 0x0642F68E72073843ULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterE) ^ 0x071C44E78764BA3FULL) ^ aOUSaltC[(((511U - aIndex) + 56U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xD6652F07E308D125ULL), 39U);
            //
            aIngress = RotL64(aOrbiterA, 47U) ^ aOrbiterE;
            aIngress = aIngress + (aOrbiterF ^ RotL64(aOrbiterC, 3U));
            aIngress = aIngress + (RotL64(aOrbiterK, 27U) ^ aOrbiterJ);
            aIngress = aIngress + RotL64(aOrbiterD, 39U);
            aIngress = TwistMix64::DiffuseB((aIngress + aScatter));
            //
            aWandererB = aWandererB ^ ((RotL64(aScatter, 21U) + RotL64(aOrbiterF, 36U)) + aOrbiterJ);
            aWandererH = aWandererH + (((RotL64(aCross, 13U) + aOrbiterE) + RotL64(aOrbiterD, 23U)) + RotL64(aCarry, 27U));
            aWandererJ = aWandererJ ^ (((RotL64(aIngress, 43U) + RotL64(aOrbiterA, 13U)) + aOrbiterD) + aWUSaltB[((aIndex + 344U)) & S_SALT1]);
            aWandererF = aWandererF + ((RotL64(aPrevious, 35U) + RotL64(aOrbiterK, 29U)) + aOrbiterA);
            aWandererK = aWandererK ^ (((RotL64(aCross, 28U) + aOrbiterC) + RotL64(aOrbiterD, 43U)) + aWUSaltD[((aIndex + 151U)) & S_SALT1]);
            aWandererC = aWandererC + ((((RotL64(aPrevious, 5U) + aOrbiterK) + RotL64(aOrbiterC, 3U)) + RotL64(aCarry, 39U)) + aWUSaltC[(((511U - aIndex) + 241U)) & S_SALT1]);
