            aOrbiterJ = (aWandererG + RotL64(aIngress, 18U)) + 0x485559BB32EBFA4DULL;
            aOrbiterI = (aWandererD + RotL64(aScatter, 29U)) + 0xBC0AF7A24FADA87AULL;
            aOrbiterH = ((aWandererB + RotL64(aPrevious, 37U)) + 0x9DA85398E7C7BBA1ULL) + aOASaltE[((aIndex + 242U)) & S_SALT1];
