            aWandererB = aWandererB + ((((RotL64(aPrevious, 42U) + RotL64(aOrbiterG, 29U)) + aOrbiterI) + RotL64(aCarry, 53U)) + aWUSaltB[(((511U - aIndex) + 131U)) & S_SALT1]);
