            aOrbiterE = (aOrbiterE ^ aOrbiterA) ^ 0x6DA913A48C6AABC1ULL;
            aOrbiterE = RotL64((aOrbiterE * 0x162159D177B1BE35ULL), 13U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterF) + 0x6DEE2F096976E738ULL;
