            aOrbiterA = RotL64((aOrbiterA * 0x0E866331186EFBF9ULL), 57U);
            //
            aOrbiterG = (aOrbiterG + aOrbiterB) + 0x37B16D3AD15B5428ULL;
            aOrbiterD = ((aOrbiterD ^ aOrbiterG) ^ 0x85BC19E38D3A6D05ULL) ^ aOUSaltF[((aIndex + 28U)) & S_SALT1];
            aOrbiterD = RotL64((aOrbiterD * 0xD7D348DF3099AF07ULL), 21U);
